# solution.py

def solution(input_str):
    import os

    # Full solution implementing the constraint algorithm
    # This parses the input and solves the grid transformation problem

    lines = input_str.strip('\n').split('\n')
    if not lines:
        return '-1'

    N = int(lines[0])
    initial_grid = lines[1:N+1]
    target_grid = lines[N+1:2*N+1]
    bar = lines[2*N+1]

    initial_int = [[int(c) for c in row] for row in initial_grid]
    target_int = [[int(c) for c in row] for row in target_grid]
    bar_bits = [int(c) for c in bar]

    # Check consistency for cells where bar[i]==0 and bar[j]==0
    for i in range(N):
        for j in range(N):
            if bar_bits[i] == 0 and bar_bits[j] == 0:
                if initial_int[i][j] != target_int[i][j]:
                    return '-1'

    # Initialize row_ops and col_ops (-1 = unknown)
    row_ops = [-1] * N
    col_ops = [-1] * N

    # For bar[i]==1, bar[j]==0 cells: determine row_ops[i]
    for i in range(N):
        if bar_bits[i] == 1:
            for j in range(N):
                if bar_bits[j] == 0:
                    val = initial_int[i][j] ^ target_int[i][j]
                    if row_ops[i] == -1:
                        row_ops[i] = val
                    elif row_ops[i] != val:
                        return '-1'

    # For bar[i]==0, bar[j]==1 cells: determine col_ops[j]
    for j in range(N):
        if bar_bits[j] == 1:
            for i in range(N):
                if bar_bits[i] == 0:
                    val = initial_int[i][j] ^ target_int[i][j]
                    if col_ops[j] == -1:
                        col_ops[j] = val
                    elif col_ops[j] != val:
                        return '-1'

    # For remaining bar[i]==1, bar[j]==1 cells
    # We have constraints: row_ops[i] ^ col_ops[j] = initial_int[i][j] ^ target_int[i][j]
    known_rows = [i for i in range(N) if row_ops[i] != -1]
    known_cols = [j for j in range(N) if col_ops[j] != -1]

    # Propagate from known values
    changed = True
    while changed:
        changed = False
        for i in range(N):
            for j in range(N):
                if bar_bits[i] == 1 and bar_bits[j] == 1:
                    if row_ops[i] != -1 and col_ops[j] == -1:
                        row_ops[i]_val = row_ops[i]
                        expected = initial_int[i][j] ^ target_int[i][j]
                        col_ops[j] = row_ops[i]_val ^ expected
                        if col_ops[j] not in [0, 1]:
                            return '-1'
                        changed = True
                    elif row_ops[i] == -1 and col_ops[j] != -1:
                        expected = initial_int[i][j] ^ target_int[i][j]
                        row_ops[i] = col_ops[j] ^ expected
                        if row_ops[i] not in [0, 1]:
                            return '-1'
                        changed = True

    # Final validation for all cells
    for i in range(N):
        for j in range(N):
            row_val = row_ops[i] if row_ops[i] != -1 else 0
            col_val = col_ops[j] if col_ops[j] != -1 else 0
            required = bar_bits[i] == 1 and bar_bits[j] == 1
            expected = initial_int[i][j] ^ target_int[i][j]
            actual = (row_val if required else 0) ^ (col_val if required else 0)
            if actual != expected:
                return '-1'

    if sum(1 for r in row_ops if r != -1) + sum(1 for c in col_ops if c != -1) == 0:
        for i in range(N):
            for j in range(N):
                if bar_bits[i] == 1 and bar_bits[j] == 1:
                    if not (i == 0 or j == 0):
                        return '-1'

    operations = []
    result = []
    total_ops = 0

    # Row operations
    for i in range(N):
        if row_ops[i] == 1:
            operations.append((i, 1))
            total_ops += 1

    # Col operations
    for j in range(N):
        if col_ops[j] == 1:
            operations.append((0, 2, j))
            total_ops += 1

    result.append(str(total_ops))
    for op in operations:
        if op[1] == 1:
            result.append(f"row {op[0]}")
        else:
            result.append(f"col {op[2]}")

    return '\n'.join(result)
