def solution(s):
    lines = s.strip().split('\n')
    m = int(lines[0])

    forbidden = {'0011', '0101', '1110', '1111'}

    dp = [0] * m  # dp[i] = number of valid sequences ending at position i
    cnt = [0] * m  # prefix sum: cnt[i] = sum of dp[0..i]

    for i in range(m):
        # Check all valid Morse code strings ending at position i
        for length in range(1, 5):
            if i + 1 - length >= 0:
                start = i + 1 - length
                sub = s[start:i+1]

                # Check if this 4-char string is forbidden
                if length == 4:
                    if sub in forbidden:
                        continue

                # Add all sequences ending at start-1, plus single valid sequences
                if start - 1 == -1:
                    # No previous position - only single valid sequences allowed
                    dp[i] = 1
                else:
                    # Count sequences extending from previous valid endings
                    count = cnt[start - 1]
                    if start > 0:
                        count = (count + start - cnt[start - 1]) % MOD
                    dp[i] = (dp[i] + count) % MOD

        # Handle 2-chars ending at i with no previous valid sequences
        if start == 0 and i == 1:
            # length 2 string at position 1-1
            sub = s[start:i+1]
            if sub not in forbidden:
                if start > 0:
                    dp[i] = (dp[i] + s[0]) % MOD

        # Better approach: use dp position by position
        dp = [0] * (i + 1)
        cnt = [0] * (i + 1)

    # Correct DP approach
    prev_dp = [0] * m
    prev_cnt = [0] * m

    dp = [0] * m

    for i in range(m):
        dp[i] = 0

        # Find how many valid sequences can end at position i
