        for length in range(1, 5):
            start = i - length + 1
            if start < 0:
                continue
            sub = s[start:i+1]
            is_forbidden = (sub in forbidden)

            if not is_forbidden:
                if start == 0:
                    dp[i] = (dp[i] + 1) % MOD
                else:
                    if prev_cnt[start - 1] > 0:
                        from_prev = prev_cnt[start - 1]
                        dp[i] = (dp[i] + from_prev) % MOD

        # Build prefix sum
        if i == 0:
            prev_cnt[i] = dp[i]
        else:
            prev_cnt[i] = (prev_cnt[i-1] + dp[i]) % MOD
        prev_dp = dp
        prev_cnt = cnt

    # Generate all outputs
    outputs = []
    for i in range(m):
        counts = 0
        for length in range(1, 5):
            start = i - length + 1
            if start < 0:
                continue
            sub = s[start:i+1]
            if sub in forbidden:
                continue
            if start == 0:
                counts = (counts + 1) % MOD
            else:
                from_prev = prev_cnt[start - 1]
                counts = (counts + from_prev) % MOD
        outputs.append(str(counts))

    return '\n'.join(outputs)
