def solution(s):
    m_sol = 1
    MOD = 10**9 + 7
    lines = s.strip().split('\n')
    m_sol = int(lines[0]) if len(lines) > 0 else 1
    chars = lines[1:]

    invalid = {'0011', '0101', '1110', '1111'}

    # psum[i] = sum of dp[0] through dp[i-1] (number of valid sequences ending before i)
    psum = [0] * (m_sol + 1)

    # dp[i][w] = number of valid sequences ending at i with the last letter of length w
    dp = [[0] * 5 for _ in range(m_sol)]

    for i in range(m_sol):
        for w in range(1, 5):
            start = i - w + 1
            if start < 0:
                continue
            segment = ''
            for k in range(start, i+1):
                segment += chars[k]

            if w == 4 and segment in invalid:
                continue

            if start == 0:
                dp[i][w] = 0
            else:
                # Sum of dp[start][all] gives us the count of sequences that can be extended
                dp[i][w] = 0
                for l in range(1, 5):
                    dp[i][w] += dp[start][l]
                dp[i][w] %= MOD

        # Update psum
        current_sum = sum(dp[i][l] for l in range(1, 5))
        psum[i+1] = (psum[i] + current_sum) % MOD

    # Calculate answer for each position
    answers = []
    for i in range(1, m_sol + 1):
        count = 0
        for l in range(1, 5):
            end = i - 1
            start = end - l + 1
            if start < 0:
                continue
            segment = ''
            for k in range(start, end + 1):
                segment += chars[k]
            if l == 4 and segment in invalid:
                continue
            if start == 0:
                count += 1
            else:
                count += dp[start - 1][l]
        answers.append(str(count % MOD))

    return '\n'.join(answers[:m_sol])
