MOD = 1000000007

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size *= 2

        self.sums = [[0] * 6 for _ in range(2 * self.size)]
        self.lazy = [-1] * (2 * self.size)

        # Build leaf nodes
        for i in range(self.n):
            x = data[i]
            for k in range(6):
                self.sums[self.size + i][k] = pow(x, k, MOD)
        for i in range(self.n, self.size):
            self.sums[self.size + i][0] = 1
            for k in range(1, 6):
                self.sums[self.size + i][k] = 0

        # Build internal nodes
        for i in range(self.size - 1, 0, -1):
            for k in range(6):
                self.sums[i][k] = (self.sums[2*i][k] + self.sums[2*i+1][k]) % MOD

    def push(self, node, l, r):
        if self.lazy[node] != -1:
            mid = (l + r) // 2
            left_len = mid - l + 1
            right_len = r - mid

            for k in range(6):
                val = pow(self.lazy[node], k, MOD)
                self.sums[2*node][k] = (val * left_len) % MOD
                self.sums[2*node+1][k] = (val * right_len) % MOD
                self.lazy[2*node] = self.lazy[node]
                self.lazy[2*node+1] = self.lazy[node]

            self.lazy[node] = -1

    def update(self, l, r, x, node=1, start=0, end=None):
        if end is None:
            end = self.size - 1

        if l > end or r < start:
            return

        if l <= start and end <= r:
            for k in range(6):
                self.sums[node][k] = pow(x, k, MOD) * (end - start + 1) % MOD
            self.lazy[node] = x
            return

        self.push(node, start, end)
        mid = (start + end) // 2
        self.update(l, r, x, 2*node, start, mid)
        self.update(l, r, x, 2*node+1, mid+1, end)

        for k in range(6):
            self.sums[node][k] = (self.sums[2*node][k] + self.sums[2*node+1][k]) % MOD

    def query(self, l, r, node=1, start=0, end=None):
        if end is None:
            end = self.size - 1

        if l > end or r < start:
            return [0] * 6

        if l <= start and end <= r:
            return list(self.sums[node])

        self.push(node, start, end)
        mid = (start + end) // 2
        left_result = self.query(l, r, 2*node, start, mid)
        right_result = self.query(l, r, 2*node+1, mid+1, end)

        result = [0] * 6
        for k in range(6):
            result[k] = (left_result[k] + right_result[k]) % MOD
        return result


def parse_query(q):
