import os

class SegmentTree:
    MOD = 1000000007

    def __init__(self, n, arr):
        self.n = n
        self.tree = [0] * (4 * n)
        self.lazy = [0] * (4 * n)
        self.mods = [0] * (4 * n)  # sum of a^p for p=0 to 5
        self.lazy_set = [False] * (4 * n)  # whether lazy is a set operation

    def _build(self, node, start, end, arr):
        if start == end:
            self.tree[node] = self.load_single_power(arr[start-1])
            self.root_power = self.load_single_power(arr[start-1])
            self.root_sum = arr[start-1]
            for i in range(6):
                self.mods[node][i] = self.MOD_pow(arr[start-1], i)
            return

        mid = (start + end) // 2
        self._build(2*node, start, mid, arr)
        self._build(2*node+1, mid+1, end, arr)
        self._update_node(node)

    def load_single_power(self, val):
        return val % self.MOD

    def MOD_pow(self, base, exp):
        result = 1
        base = base % self.MOD
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % self.MOD
            base = (base * base) % self.MOD
            exp //= 2
        return result

    def _update_node(self, node, dist_sum, total_len):
        if dist_sum == 0:
            for i in range(6):
                self.mods[node][i] = (i * total_len * self.tree[node]) % self.MOD
        else:
            self._calc_mod(node, total_len)

    def _calc_mod(self, node, total_len):
        raise NotImplementedError

    def update(self, p, l, r, x, node, start, end):
        if start > end or node > len(self.mods):
            return
        self.update_lazy(p, l, r, x, node, start, end)
        self.update_node(node, p, l, r, x, start, end)

    def update_lazy(self, p, l, r, x, node, start, end):
        if l <= start and end <= r:
            self.lazy[node] = (r - start + 1) * (x % self.MOD)
            self.tree[node] = x
            self.lazy_set[node] = True
            for i in range(6):
                self.mods[node][i] = (i * (r - start + 1)) % self.MOD
        else:
            if not self._lazy_is_set(node):
                self.apply_pending(node)
            else:
                mid = (start + end) // 2
                if self._range_overlap(l, r, start, mid):
                    self.update_lazy(p, l, r, x, 2*node, start, mid)
                if self._range_overlap(l, r, mid+1, end):
                    self.update_lazy(p, l, r, x, 2*node+1, mid+1, end)
                self._pull(node)

    def _pull(self, node):
        self.tree[node] = (self.tree[2*node] + self.tree[2*node+1]) % self.MOD
        for i in range(6):
