class SegmentTree:
    def __init__(self, n, arr):
        self.n = n
        self.tree = [[0]*6 for _ in range(4*n)]
        self.lazy = [[0]*6 for _ in range(4*n)]
        self.lazy_set = [False]*(4*n)

        self.build(arr)

    def build(self, arr):
        self._build(1, 0, self.n-1, arr)

    def _build(self, node, start, end, arr):
        if start == end:
            val = arr[start]
            for i in range(6):
                self.tree[node][i] = pow_mod(val, i, MOD)
            return

        mid = (start + end) // 2
        self._build(2*node, start, mid, arr)
        self._build(2*node+1, mid+1, end, arr)

        for i in range(6):
            self.tree[node][i] = self.tree[2*node][i] + self.tree[2*node+1][i]
            self.tree[node][i] %= MOD

