                ox = found_m['intercept_x']
                oy = y_target
                dy_sign = -1 if found_m['ctype'] == 'F' else 1
                angle = math.atan2(-math.sin(angle), math.cos(angle))
                best_score = max(best_score, score + found_m['score'])
            else:
                break

        return best_score

    best_score = max(ray_trace(0, hl, math.pi/8, set()),
