Looking at this problem, I need to solve a game theory optimal play problem where two teams alternate picks and bans to maximize their relative advantage.

Let me analyze:
- Team 1 wants to maximize (Team1_strength - Team2_strength)
- Team 2 wants to maximize (Team2_strength - Team1_strength), which is minimizing (Team1_strength - Team2_strength)
- This is a zero-sum game with perfect information
- At each turn, the player makes a deterministic optimal choice

For this solution, I'll implement a minimax DP with memoization. The key insight is that in optimal play, when a team picks, they take the best available hero, and when they ban, they ban the strongest remaining hero.

```python
from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    s = list(map(int, lines[1].split()))
    m = int(lines[2])
    actions = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        actions.append((parts[0], int(parts[1])))

    # Sort heroes by strength descending
    s_sorted = sorted(s, reverse=True)

    @lru_cache(maxsize=None)
    def solve(available_mask, turn, team1_sum, team2_sum):
        if turn == m:
            return team1_sum - team2_sum

        action = actions[turn]
        act_type = action[0]  # 'p' or 'b'
        who_team = action[1]

        # Get available heroes sorted by strength
        available = [i for i in range(n) if (available_mask >> i) & 1]

        # Find indices in sorted strengths
        available_str = [s_sorted[i] for i in available]
        if not available_str:
            return team1_sum - team2_sum

        # Best available hero (highest strength)
        best_idx = available_str.index(max(available_str))
        best_val = available_str[best_idx]

        if act_type == 'p':
            if who_team == 1:
                # Team 1 picks for themselves
                return solve(available_mask | (1 << available[best_idx]), turn + 1, team1_sum + best_val, team2_sum)
            else:
                # Team 2 picks for themselves  
                return solve(available_mask | (1 << available[best_idx]), turn + 1, team1_sum, team2_sum + best_val)
        else:
            # Ban - strongest hero removed
            return solve(available_mask | (1 << available[best_idx]), turn + 1, team1_sum, team2_sum)

    result = solve(0, 0, 0, 0)
    return str(result) + '\n'
